from collections import defaultdict, deque

def isEulerCircuilt(V, adj):
    # Check if the graph is connected
    visited = [False] * V
    start = 0
    while start < V and len(adj[start]) == 0:
        start += 1
    if start == V:
        return 2  # empty graph (trivial case)

    queue = deque([start])
    visited[start] = True
    count = 1

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                count += 1
                queue.append(v)

    if count != V:
        return 0

    # Check degrees
    odd_degree = 0
    for neighbors in adj:
        if len(neighbors) % 2 != 0:
            odd_degree += 1

    if odd_degree == 0:
        return 2
    elif odd_degree == 2:
        return 1
    else:
        return 0
